// Houdini VEX code for procedural destruction
// This runs on each point/primitive in the geometry

// Get the impact position from a detail attribute
vector impactPos = point(1, "P", 0);
float impactRadius = chf("impact_radius");
float strength = chf("strength");

// Get current point position
vector pos = @P;

// Calculate distance from impact
float dist = distance(pos, impactPos);

// Falloff
float falloff = 1 - smooth(0, impactRadius, dist);

// Apply explosion force (push points away from impact)
vector dir = normalize(pos - impactPos);
@P += dir * strength * falloff;

// Add random variation for debris
@P += rand(@ptnum) * 0.1 * falloff;

// Store velocity for simulation (if needed)
@v = dir * strength * falloff * 10;

// Set color for visual feedback
@Cd = falloff;

// Create fracture lines: if close to impact, break apart
if (falloff > 0.3) {
    @group_debris = 1;
}
